package ktanesolver.module.modded.regular.thedigit;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.enums.PortType;import ktanesolver.logic.*;class TheDigitSolverTest{private final TheDigitSolver solver=new TheDigitSolver();@Test void appliesEveryStepInSourceOrder(){BombEntity b=new BombEntity();b.setSerialNumber("AB1C23");b.setAaBatteryCount(2);b.setDBatteryCount(1);b.setIndicators(Map.of("A",true,"B",true,"C",false));b.replacePortPlates(List.of(Set.of(PortType.RJ45)));var out=solve(b);assertThat(out.steps()).containsExactly(6,9,18,17,17,14,14,16,16);assertThat(out.answer()).isEqualTo(6);}@Test void handlesNoPortsNegativeAndBatteryHolderBonus(){BombEntity b=new BombEntity();b.setSerialNumber("ABCD01");assertThat(solve(b).answer()).isEqualTo(1);b.setAaBatteryCount(4);b.setDBatteryCount(1);assertThat(solve(b).steps().get(4)).isEqualTo(8);}@Test void requiresSerialDigit(){BombEntity b=new BombEntity();b.setSerialNumber("ABCDEF");assertThat(solver.solve(new RoundEntity(),b,new ModuleEntity(),new TheDigitInput())).isInstanceOf(SolveFailure.class);}@SuppressWarnings("unchecked")private TheDigitOutput solve(BombEntity b){return((SolveSuccess<TheDigitOutput>)solver.solve(new RoundEntity(),b,new ModuleEntity(),new TheDigitInput())).output();}}
